package com.smritisathi.app.core;
import android.app.*;import android.content.*;import android.graphics.Color;import android.view.*;import android.widget.*;import android.graphics.drawable.GradientDrawable;
public class UI { public static int blue=Color.rgb(49,130,206); public static int bg=Color.rgb(247,250,252); public static LinearLayout page(Context c){LinearLayout l=new LinearLayout(c);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(20,20,20,20);l.setBackgroundColor(bg);return l;} public static TextView title(Context c,String s){TextView t=new TextView(c);t.setText(s);t.setTextSize(26);t.setTextColor(Color.rgb(45,55,72));t.setTypeface(null,1);t.setPadding(0,8,0,16);return t;} public static TextView text(Context c,String s){TextView t=new TextView(c);t.setText(s);t.setTextSize(18);t.setTextColor(Color.rgb(74,85,104));t.setPadding(0,6,0,10);return t;} public static Button button(Context c,String s){Button b=new Button(c);b.setText(s);b.setTextSize(18);b.setAllCaps(false);return b;} public static EditText edit(Context c,String hint){EditText e=new EditText(c);e.setHint(hint);e.setTextSize(18);e.setSingleLine();e.setPadding(14,8,14,8);return e;} public static void toast(Context c,String s){Toast.makeText(c,s,Toast.LENGTH_LONG).show();} public static void dialog(Context c,String title,String msg){new AlertDialog.Builder(c).setTitle(title).setMessage(msg).setPositiveButton("OK",null).show();} public static TextView card(Context c,String s){TextView t=text(c,s);GradientDrawable g=new GradientDrawable();g.setColor(Color.WHITE);g.setCornerRadius(18);g.setStroke(2,Color.rgb(226,232,240));t.setBackground(g);t.setPadding(18,18,18,18);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,8,0,8);t.setLayoutParams(p);return t;}}
